def armor(d,a=20,t=0):return d*(1-min(20,max(a/5,a-d/(2+t/4)))/25)
def main():
 rows=load('catalogue-provenance.json');native={x['id']:x for x in load('native-attributes.json')};review=[]
 for row in rows:
  id=row['id'];n=native[id];family=row['family'];damage=n['attack_damage_total'];speed=n['attack_speed_total'];special=SPECIAL.get(id)
  recipes=[x for x in row['resource_references'] if x['role']=='recipe_output'];loot=[x['path'] for x in row['resource_references'] if '/loot_table/' in x['path']]
  acquisition=special[0] if special else '; '.join([x['path'] for x in recipes]+loot)
  if not acquisition:acquisition='UNRESOLVED: no recipe/loot source found'
  if special:effect=special[1];sources=special[2];decision=special[3]
  elif family=='flails':effect='Mace armor pressure .22 (max+45%), push .65; RMB charge18t/CD40t LOS4b damage7+tierBonus; disables shields. One charge hit, no chain physics';sources='combat/FlailItem.java; combat/MaceItem.java; combat/CombatEquipment.java';decision='ART/ANIMATION: flat material flails require assembled geometry'
  elif family in ['throwing_knives','sulitsas']:
   bonus={'stone':1,'gold':0,'iron':2,'silver':2,'diamond':3,'perunite':2.5,'netherite':4}[id.split('_')[0]];knife=family=='throwing_knives';thrown=2+bonus*.35 if knife else 5+bonus
   effect=f'thrownDamage {thrown:g}, '+('instant throw CD8t; velocity1.65; knife loss/loyalty pickup policies' if knife else 'charge>=6t, maxspeed2.5 at20t, CD16t; one exact component-bearing stack/projectile')+'; damage type trident; owner/LOS projectile targeting';sources='combat/ThrowingWeaponItem.java; combat/WeaponProjectile.java';decision='KEEP mechanics pending effects QA; ART/ANIMATION distinct knife vs dart'
  elif family=='maces':effect='MaceItem pressure/push read from exact constructor; armor-pressure multiplier applied before vanilla armor, capped+45%; club is SwordItem with push, not MaceItem';sources='combat/MaceItem.java; combat/CombatEquipment.java; item/ClubItem.java';decision='KEEP/FIX geometry after source render; ANIMATION; BALANCE for perunite_mace'
  elif family=='spears':effect='SpearItem native reach+1.25 and push .18; ancient/restored BurialWeapon is SwordItem, NO reach modifier despite spear name';sources='item/SpearItem.java; kurgan/BurialWeapon.java';decision='KEEP stats; ANIMATION/grip; BUG/BALANCE BurialWeapon reach discrepancy for owner review' if id in ['ancient_spear','restored_spear'] else 'KEEP stats; ART/ANIMATION/grip review'
  else:effect='Native charged melee; SwordItem sweep/enchant pipeline if matching source class. No standalone item ability found; shared RuneEffects/FolkEquipment modifiers excluded from baseline';sources=n['class'];decision='KEEP stats; inspect family geometry and ANIMATION'
  if id in ['ancient_carolingian_sword','restored_carolingian_sword','ancient_chekan','chekan']:decision+='; BUG requested durability overridden by tier constructor'
  stage='Inference: early bone/wood' if id in ['bone_knife','club','carved_staff'] else 'Inference: armorer station/material tier, not only ore tier'
  if special:stage='Source prerequisite chain: '+special[0]
  if id.startswith(('ancient_','restored_')):stage='Burial exploration and combat; restoration also armorer station +iron/leather/stick'
  bonus=1.0
  if family=='maces' or family=='flails':
   pressure={'wooden_mace':.2,'stone_mace':.3,'mace':.35,'silver_mace':.3,'perunite_mace':.4,'ancient_chekan':.22,'chekan':.3}.get(id,.22)
   if id!='club':bonus=1+min(.45,20*pressure/20)
  dps=damage*min(speed,2);armored=armor(damage*bonus)*min(speed,2)
  conditional=family in ['bows','staves'] or id=='karachun_scythe'
  competitors='vanilla wood/stone/iron/diamond/netherite swords: 4/5/6/7/8 at1.6s^-1 =>6.4/8/9.6/11.2/12.8 raw DPS; same-tier axe high burst; same-tier mod spear reach4.25 and mace pressure; pick comparable material/prereqs'
  if family in ['bows','staves']:competitors='vanilla bow full draw20t velocity3/base2; crossbow charge25t (Quick Charge changes), same-stage short/heavy/Finist and magic utility, ammo/time/cost constraints'
  review.append(row|{'native':n,'acquisition':acquisition,'stage_and_prerequisites':stage,'rarity_difficulty':'Exact recipes/loot conditions in resource_references; boss/trial sources in effects_sources; world availability is not a measured completion time','effects':effect,'effects_sources':sources,'comparison':competitors,'damage_type':'projectile/trident/magic and ability-specific; see effects' if conditional or family in ['sulitsas','throwing_knives'] else 'player melee (armor applies); specials separately','analytical_melee_dps':None if conditional else round(dps,4),'analytical_armor20_toughness0_dps':None if conditional else round(armored,4),'dps_limits':'Analytical stationary equal full-charge hits, max2 equal hits/sec from hurt cooldown; excludes crits/enchant/runes/aiming/movement/boss phase. NOT measured runtime DPS; specials above are separate budgets','decision':decision,'audit_state':'SOURCE_REVIEW: per-item evidence collected; source renders and unresolved acquisition remain under investigation'})
 dump('audit-68.json',review)
 with (O/'audit-68.csv').open('w',encoding='utf-8-sig',newline='') as f:
  writer=csv.writer(f);writer.writerow(['ID','RU','family','actual_damage','actual_speed','actual_reach','actual_durability','acquisition','stage','specials','analytical_melee_DPS','armor20_DPS','comparison','decision','runtime'])
  for x in review:writer.writerow([x['id'],x['ru'],x['family'],x['native']['attack_damage_total'],x['native']['attack_speed_total'],x['native']['reach_total'],x['native']['max_damage'],x['acquisition'],x['stage_and_prerequisites'],x['effects'],x['analytical_melee_dps'],x['analytical_armor20_toughness0_dps'],x['comparison'],x['decision'],x['runtime']])
 lines=['# #157 — источник и аналитическая матрица 68 оружейных IDs','', 'IN_PROGRESS. Это аудит исходников, не замеры боёв и не игровая приёмка. Ни один production-файл оружия не менялся.','', 'Полные поля/точные рецепты/loot conditions/paths/SHA: `audit-68.json`, удобная таблица `audit-68.csv`. Атрибуты получены реальными конструкторами в изолированном offline Java fixture. Forge registry открыт только в отдельном тестовом процессе; миры/существа/client/server не создаются.','', '## Расчёт','', 'База игрока: damage1, speed4, reach3; к ней добавлены реальные ItemAttributeModifiers. Для одинаковых ударов без критов верхняя частота min(speed,2) из-за hurt cooldown. Броня20/toughness0: damage × (1−clamp(armor−damage/(2+toughness/4),armor/5,20)/25); Mace pressure добавляется до брони. Это сравнимая аналитическая оценка, не измеренный DPS. У снарядов, контроля, призыва и косы дан отдельный бюджет/тайминг; fist attributes не выдаются за их урон.','', '## Матрица','', '| ID | RU | damage / speed / reach | durability | raw melee DPS | решение |','|---|---|---|---|---|---|']
 for x in review:
  n=x['native'];lines.append(f"| {x['id']} | {x['ru']} | {n['attack_damage_total']:g} / {n['attack_speed_total']:.2f} / {n['reach_total']:g} | {n['max_damage']} | {x['analytical_melee_dps'] if x['analytical_melee_dps'] is not None else 'ability/ammo: см. JSON'} | {x['decision']} |")
 lines+=['','## Открытые доказательные вопросы','', '- Посох Велеса: источник выдачи в survival пока не подтверждён; не придумывать рецепт.','- Прочность ряда SwordItem/TieredItem не соответствует p.durability(...) в вызывающем конструкторе: native component показывает tier value. Исправление требует решения о фактических числах.','- ThunderAxe: вторичный magic1 вызывается после melee в hurtEnemy; проверить vanilla invulnerability/call order перед исправлением.','- Исходные GUI/held/player projections ещё готовятся; KEEP/FIX художественных частей не считать окончательным по одному наличию PNG.','- Runtime, PvP/MP, FPS, реальное время убийства и 1P/3P владелец: NOT_RUN / OWNER_PENDING.','', '| REQUIREMENT | EVIDENCE | RESULT |','|---|---|---|','| 68 IDs и параметры из настоящих конструкторов | native-attributes.json; generated factories + provenance | PASS |','| Источники получения/эффекты/сравнение каждого ID | audit-68.json/csv; неясности перечислены | IN_PROGRESS: Veles acquisition |','| Полная художественная оценка GUI/1P/3P | source renders ещё готовятся | NOT_RUN |','| Никаких production изменений во время #157 | baseline.json, отдельная preservation-проверка | pending verification |','| Java21 clean build/resource/JAR | audit-build.log; gate report готовится | IN_PROGRESS |','| Игровой бой/визуал/MP/FPS | 0 game launches | NOT_RUN / OWNER_PENDING |']
 (O/'AUDIT-157.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 # Real before assets, including standalone held and charge states, before any art mutation.
 files={p['path'] for x in rows for key in ['models','textures'] for p in x[key]}
 for p in (R/'src/main/java/org/slavicmyths').rglob('*.java'):
  if any(part in p.parts for part in ['combat','gorynych']) or p.name in ['WeaponHands.java','NightClient.java','FrostClient.java','Quest185ItemRenderer.java']:files.add(p.relative_to(R).as_posix())
 if not (O/'before-source.zip').exists():
  with zipfile.ZipFile(O/'before-source.zip','w',zipfile.ZIP_DEFLATED) as z:
   for p in sorted(files):z.write(R/p,p)
  dump('before-manifest.json',{p:hashlib.sha256((R/p).read_bytes()).hexdigest() for p in sorted(files)})
 print('68 rows, native metrics + source acquisition/effects + analytical comparisons; audit remains IN_PROGRESS')
if __name__=='__main__':main()
